<script setup>
import { ref } from 'vue'
import { SHOPPING_OPERATION_PAGE_EVENTS, SHOPPING_OPERATION_PAGE_PROPS, localizeOperationPage } from './shopping-operation-page-contract'

const props = defineProps(SHOPPING_OPERATION_PAGE_PROPS)
const emit = defineEmits(SHOPPING_OPERATION_PAGE_EVENTS)
const l = (zh, en) => localizeOperationPage(props.languageBase, zh, en)
const pendingDeleteId = ref('')
const requestDelete = (orderId) => {
  if (pendingDeleteId.value !== orderId) {
    pendingDeleteId.value = orderId
    return
  }
  pendingDeleteId.value = ''
  emit('delete-order', orderId)
}
</script>

<template>
  <main class="ik-ops" :data-page="pageKey" data-testid="shopping-store-operation-page">
    <header class="ik-opbar"><button type="button" @click="emit('back')"><i class="fas fa-arrow-left"></i></button><strong><span>IKEA</span> KOREA</strong><div><button type="button" data-testid="shopping-open-service" @click="emit('open-service')">{{ l('服务','Service') }}</button><button type="button" @click="emit('open-orders')">{{ l('订单','Orders') }}</button><button type="button" @click="emit('open-cart')"><i class="fas fa-bag-shopping"></i><b v-if="cartQuantity">{{ cartQuantity }}</b></button></div></header>

    <section v-if="pageKey === 'cart'" id="shopping-cart" class="ik-list">
      <header><div><p>{{ l('购物清单','SHOPPING LIST') }} / {{ cartQuantity }}</p><h1>{{ l('核对商品，再选择配送与支付','Review items before delivery and payment') }}</h1></div><i class="fas fa-list-check"></i></header>
      <div v-if="!cartItems.length" class="ik-empty"><i class="fas fa-bag-shopping"></i><h2>{{ l('购物清单还是空的','Your shopping list is empty') }}</h2><button type="button" @click="emit('back')">{{ l('继续选购','Continue shopping') }}</button></div>
      <div v-else class="ik-cart-layout">
        <section>
          <article v-for="line in cartItems" :key="line.productId">
            <span><img v-if="productImageUrl(line.product)" :src="productImageUrl(line.product)" :alt="productDisplayTitle(line.product)" /><i v-else :class="productCategoryIcon(line.product)"></i></span>
            <div><small>{{ l('商品','ITEM') }}</small><strong>{{ productDisplayTitle(line.product) }}</strong><b>{{ formatOrderItemSubtotal({ ...line, unitPriceCents: line.product.priceCents, currency: line.currency }) }}</b><div class="ik-quantity"><button type="button" :aria-label="l('减少数量','Decrease quantity')" @click="emit('update-quantity', line.productId, -1)">−</button><span>{{ line.quantity }}</span><button type="button" :aria-label="l('增加数量','Increase quantity')" @click="emit('update-quantity', line.productId, 1)">+</button></div></div>
          </article>
        </section>
        <aside><p>{{ l('订单摘要','ORDER SUMMARY') }}</p><strong>{{ cartTotalLabel }}</strong><dl><div><dt>{{ l('商品数量','Items') }}</dt><dd>{{ cartQuantity }}</dd></div><div><dt>{{ l('配送与费用','Delivery & fees') }}</dt><dd>{{ l('结算时确认','Review at checkout') }}</dd></div></dl><label><input :checked="giftEnabled" type="checkbox" data-testid="shopping-gift-enabled" @change="emit('update:giftEnabled', $event.target.checked)" />{{ l('作为礼物购买','Purchase as a gift') }}</label><select v-if="giftEnabled" :value="giftContactId" data-testid="shopping-gift-contact" @change="emit('update:giftContactId', $event.target.value)"><option value="">{{ l('手动填写收件人','Manual recipient') }}</option><option v-for="contact in giftRecipientOptions" :key="contact.id" :value="String(contact.id)">{{ contact.name }}</option></select><input v-if="giftEnabled" :value="giftRecipientName" data-testid="shopping-gift-name" :placeholder="l('收件人姓名','Recipient name')" @input="emit('update:giftRecipientName', $event.target.value)" /><button type="button" data-testid="shopping-checkout" @click="emit('checkout')">{{ l('进入结算','Continue to checkout') }}</button></aside>
      </div>
    </section>

    <section v-else-if="pageKey === 'orders'" id="shopping-orders" class="ik-orders">
      <header><div><p>{{ l('我的订单','MY ORDERS') }}</p><h1>{{ l('购买、配送与售后记录','Purchases, delivery, and support') }}</h1></div><button type="button" @click="emit('open-logistics')">{{ l('查看配送','Delivery') }} <i class="fas fa-arrow-right"></i></button></header>
      <div v-if="!orders.length" class="ik-empty"><i class="fas fa-receipt"></i><h2>{{ l('还没有订单','No orders yet') }}</h2></div>
      <article v-for="order in orders" :key="order.id" :data-testid="`shopping-order-${order.id}`">
        <span class="ik-order-mark"><i class="fas fa-box"></i></span><div><small>{{ formatLogisticsDate(order.createdAt) }}</small><h2>{{ order.items.map(item => item.title).join(' / ') }}</h2><p>{{ order.itemCount }} {{ l('件商品','items') }} · {{ formatOrderTotal(order) }}</p><b>{{ orderStatusLabel(order.status) }}</b></div><button type="button" :data-testid="`shopping-open-order-detail-${order.id}`" @click="emit('open-order', order.id)">{{ l('查看订单','View order') }}</button><button type="button" class="ik-delete" :class="{ confirm: pendingDeleteId === order.id }" @click="requestDelete(order.id)">{{ pendingDeleteId === order.id ? l('确认删除','Confirm') : l('删除','Delete') }}</button>
      </article>
    </section>

    <section v-else-if="pageKey === 'logistics'" class="ik-delivery" data-testid="shopping-logistics-panel">
      <header><button type="button" @click="emit('open-orders')"><i class="fas fa-arrow-left"></i>{{ l('订单','Orders') }}</button><p>{{ l('配送进度','DELIVERY STATUS') }}</p><h1>{{ l('只显示订单已记录的配送信息','Recorded delivery updates') }}</h1></header>
      <article v-for="row in logisticsRows" :key="row.order.id" :data-testid="`shopping-logistics-order-${row.order.id}`"><span><i class="fas fa-truck"></i></span><div><small>{{ row.latestEvent ? logisticsEventTypeLabel(row.latestEvent.type) : l('订单已创建','Order created') }}</small><h2>{{ row.title }}</h2><p>{{ row.latestEvent?.summary || row.summary }}</p><b :data-testid="`shopping-logistics-status-${row.order.id}`">{{ logisticsStatusLabel(row.status) }}</b><em v-if="row.latestEvent" :data-testid="`shopping-logistics-latest-event-${row.order.id}`">{{ [row.latestEvent.pickupPoint, row.latestEvent.trackingCode].filter(Boolean).join(' / ') }}</em></div><button type="button" :data-testid="`shopping-logistics-detail-${row.order.id}`" @click="emit('open-order', row.order.id)">{{ l('订单详情','Order details') }}</button></article>
      <div v-if="!logisticsRows.length" class="ik-empty"><i class="fas fa-truck"></i><h2>{{ l('暂无配送记录','No delivery records') }}</h2></div>
    </section>

    <section v-else-if="selectedOrder" class="ik-order-detail" data-testid="shopping-order-detail-panel">
      <header><button type="button" data-testid="shopping-close-order-detail" @click="emit('close-order')"><i class="fas fa-arrow-left"></i></button><div><p>{{ l('订单详情','ORDER DETAIL') }}</p><h1>{{ selectedOrder.id }}</h1></div><b data-testid="shopping-order-detail-status">{{ orderStatusLabel(selectedOrder.status) }}</b></header>
      <section class="ik-order-summary"><div><span>{{ l('订单总额','TOTAL') }}</span><strong data-testid="shopping-order-detail-total">{{ formatOrderTotal(selectedOrder) }}</strong></div><div><span>{{ l('商品数量','ITEMS') }}</span><strong>{{ selectedOrder.itemCount }}</strong></div></section>
      <section class="ik-order-items"><article v-for="item in selectedOrder.items" :key="item.id" :data-testid="`shopping-order-detail-item-${item.productId}`"><span><i class="fas fa-box-open"></i></span><div><h2>{{ item.title }}</h2><p>{{ item.quantity }} × {{ formatOrderItemSubtotal(item) }}</p></div></article></section>
      <section class="ik-timeline" data-testid="shopping-order-detail-timeline"><h2>{{ l('订单记录','ORDER UPDATES') }}</h2><article v-for="event in selectedOrder.events || []" :key="event.id" :data-testid="`shopping-order-detail-event-${event.id}`"><span>{{ formatLogisticsDate(event.createdAt) }}</span><strong>{{ logisticsEventTypeLabel(event.type) }}</strong><p>{{ event.summary || event.title }}</p></article><p v-if="!selectedOrder.events?.length" data-testid="shopping-order-detail-timeline-empty">{{ l('还没有新增订单动态。','No additional order updates yet.') }}</p></section>
      <footer><button type="button" data-testid="shopping-order-detail-complete" :disabled="!canCompleteOrder(selectedOrder)" @click="emit('complete-order', selectedOrder.id)">{{ l('确认完成','Mark complete') }}</button><button type="button" data-testid="shopping-order-detail-cancel" :disabled="!canCancelOrder(selectedOrder)" @click="emit('cancel-order', selectedOrder.id)">{{ l('取消订单','Cancel order') }}</button><button type="button" data-testid="shopping-order-detail-delete" :class="{ confirm: pendingDeleteId === selectedOrder.id }" @click="requestDelete(selectedOrder.id)">{{ pendingDeleteId === selectedOrder.id ? l('再次点击确认','Tap again to confirm') : l('删除记录','Delete record') }}</button></footer>
    </section>
  </main>
</template>

<style scoped>
.ik-ops{--blue:#0058a3;--yellow:#ffda1a;min-height:100%;color:#111;background:#f4f4f2;font-family:Arial,"Noto Sans KR",sans-serif}.ik-opbar{position:sticky;top:0;z-index:20;height:62px;padding:0 16px;display:grid;grid-template-columns:42px 1fr auto;align-items:center;border-bottom:1px solid #ddd;background:#fff}.ik-opbar>strong{font-size:11px}.ik-opbar>strong span{padding:6px 8px;color:var(--yellow);background:var(--blue);font-size:14px}.ik-opbar>div{display:flex;gap:14px}.ik-opbar button{position:relative;font-size:8px;font-weight:900}.ik-opbar b{position:absolute;right:-8px;top:-9px;min-width:16px;height:16px;display:grid;place-items:center;border-radius:9px;color:#fff;background:var(--blue);font-size:7px}.ik-list>header{padding:34px 24px;display:grid;grid-template-columns:1fr auto;align-items:end;background:#fff}.ik-list header p,.ik-orders header p,.ik-delivery header p,.ik-order-detail header p{margin:0;color:var(--blue);font-size:8px;font-weight:900;letter-spacing:.1em}.ik-list h1{max-width:650px;margin:9px 0 0;font-size:38px;line-height:1}.ik-list>header>i{color:var(--blue);font-size:64px}.ik-cart-layout{padding:18px 20px 60px;display:grid;grid-template-columns:1.25fr .75fr;gap:12px}.ik-cart-layout>section{display:grid;gap:9px}.ik-cart-layout article{padding:12px;display:grid;grid-template-columns:125px 1fr;gap:14px;background:#fff}.ik-cart-layout article>span{aspect-ratio:1;display:grid;place-items:center;overflow:hidden;color:var(--blue);background:#eee;font-size:38px}.ik-cart-layout img{width:100%;height:100%;object-fit:cover}.ik-cart-layout article small,.ik-cart-layout article strong,.ik-cart-layout article b{display:block}.ik-cart-layout article small{color:#777;font-size:7px}.ik-cart-layout article strong{margin-top:6px;font-size:14px}.ik-cart-layout article b{margin-top:8px;font-size:10px}.ik-quantity{width:112px;margin-top:13px;display:grid;grid-template-columns:34px 1fr 34px;border:1px solid #ccc}.ik-quantity>*{height:34px;display:grid;place-items:c